+const record: SourceRecord = { id: "rec_selected", sourceId: "src_selected", text: "Synthetic selected content\nsecond line <script>bad()</script>", locator: "row 2", fields: { synthetic: "original field value", columns: [1, 2] } };
+function request(): HilReportRequest {
