+    expect(write).toHaveBeenCalledWith("/tmp/report.pdf", new TextEncoder().encode("%PDF-synthetic"));
+    expect(JSON.stringify(req)).toBe(before);
+  });
+  it("surfaces dialog, rendering and disk errors", async () => {
+    const saved = async () => ({ canceled: false, filePath: "/tmp/report.pdf" });
+    await expect(exportHilReportPdf(request(), async () => { throw new Error("Dialog unavailable"); })).rejects.toThrow("Dialog unavailable");
+    await expect(exportHilReportPdf(request(), saved, async () => { throw new Error("Print failed"); })).rejects.toThrow("Print failed");
